import React from 'react';
import {Card} from 'antd';
import {ProForm, ProFormSwitch} from '@ant-design/pro-form';
import {BadgeRibbon} from '@yookue/ant-buddy-pro';


export default () => {
    const [emptyText, setEmptyText] = React.useState<boolean>(false);
    const [transparent, setTransparent] = React.useState<boolean>(false);

    return (
        <>
            <ProForm
                name='BadgeRibbon_demo.en-US'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProForm.Group>
                    <ProFormSwitch
                        label='Empty Text'
                        checkedChildren='True'
                        unCheckedChildren='False'
                        fieldProps={{
                            checked: emptyText,
                            onChange: setEmptyText,
                        }}
                    />
                    <ProFormSwitch
                        label='Transparent'
                        checkedChildren='True'
                        unCheckedChildren='False'
                        fieldProps={{
                            checked: transparent,
                            disabled: emptyText,
                            onChange: setTransparent,
                        }}
                    />
                </ProForm.Group>
            </ProForm>
            <BadgeRibbon
                color='lime'
                transparent={transparent}
                text={emptyText ? undefined : (
                    <span style={{
                        color: transparent ? 'green' : undefined,
                        marginRight: transparent ? 8 : 0,
                    }}>
                        ant-buddy-pro
                    </span>
                )}
            >
                <Card title='BadgeRibbon'>
                    The quick brown fox jumps over a lazy dog.
                </Card>
            </BadgeRibbon>
        </>
    );
}
