import {Row, Col, Divider} from 'antd';
import datePickerLocale from 'antd/es/date-picker/locale/en_US';
import {ProForm, ProFormDatePicker, ProFormRadio, ProFormSwitch, ProFormDependency} from '@ant-design/pro-form';
import {CompactTuple, type BeforeAfterType} from '@yookue/ant-buddy-pro';
import {type TuplePresetStyle} from '@yookue/ant-buddy-pro/field/CompactTuple';
import dayjs from 'dayjs';


export default () => {
    // noinspection DuplicatedCode
    const [formReadonly, setFormReadonly] = React.useState<boolean>(false);
    const [widthBlock, setWidthBlock] = React.useState<boolean>(false);
    const [addonPos, setAddonPos] = React.useState<BeforeAfterType>('after');
    const [presetStyle, setPresetStyle] = React.useState<TuplePresetStyle | false>('field-prior');

    return (
        <>
            <ProForm
                name='CompactTuple_demo.en-US'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProForm.Group>
                    <ProFormSwitch
                        label='Form Readonly'
                        checkedChildren='True'
                        unCheckedChildren='False'
                        fieldProps={{
                            checked: formReadonly,
                            onChange: setFormReadonly,
                        }}
                    />
                    <ProFormSwitch
                        label='Width Block'
                        checkedChildren='True'
                        unCheckedChildren='False'
                        fieldProps={{
                            checked: widthBlock,
                            onChange: setWidthBlock,
                        }}
                    />
                </ProForm.Group>
                <ProFormRadio.Group
                    label='Addon Position'
                    radioType='button'
                    fieldProps={{
                        value: addonPos,
                        buttonStyle: 'solid',
                        disabled: formReadonly,
                        onChange: (event) => {
                            setAddonPos(event.target?.value);
                        }
                    }}
                    options={[
                        {label: 'Before', value: 'before'},
                        {label: 'After', value: 'after'},
                        {label: 'False', value: false},
                    ]}
                />
                <ProFormRadio.Group
                    label='Preset Style'
                    radioType='button'
                    fieldProps={{
                        value: presetStyle,
                        buttonStyle: 'solid',
                        disabled: formReadonly,
                        onChange: (event) => {
                            setPresetStyle(event.target?.value);
                        }
                    }}
                    options={[
                        {label: 'Field-Prior', value: 'field-prior'},
                        {label: 'Addon-Prior', value: 'addon-prior'},
                        {label: 'False', value: false},
                    ]}
                />
            </ProForm>
            <Divider/>
            <ProForm
                name='CompactTuple_test'
                layout='vertical'
                autoFocusFirstInput={false}
                readonly={formReadonly}
                submitter={false}
            >
                <Row gutter={[12, 0]}>
                    <Col span={12}>
                        <ProFormDatePicker
                            name='identityStart'
                            label='Start Date'
                            placeholder='Start Date'
                            fieldProps={{
                                style: {width: '100%'},
                                locale: datePickerLocale,
                            }}
                        />
                    </Col>
                    <Col span={12}>
                        <CompactTuple
                            field={(
                                <ProFormDependency name={['identityStart', 'identityInfinite']} shouldUpdate={true}>
                                    {({identityStart, identityInfinite}) => {
                                        return (
                                            <ProFormDatePicker
                                                name='identityEnd'
                                                label='End Date'
                                                placeholder='End Date'
                                                fieldProps={{
                                                    disabled: identityInfinite,
                                                    disabledDate: (date: any) => date < dayjs(identityStart),
                                                    style: {width: '100%'},
                                                    locale: datePickerLocale,
                                                }}
                                            />
                                        );
                                    }}
                                </ProFormDependency>
                            )}
                            addon={(
                                <ProFormSwitch
                                    name='identityInfinite'
                                    label='Infinite'
                                    fieldProps={{
                                        defaultChecked: false,
                                        checkedChildren: 'Yes',
                                        unCheckedChildren: 'No',
                                        style: {
                                            margin: '2px 6px',
                                        }
                                    }}
                                />
                            )}
                            addonPos={addonPos}
                            addonBorder={true}
                            addonMarginLeft={addonPos === 'after'}
                            addonMarginRight={addonPos === 'before'}
                            widthBlock={widthBlock}
                            presetStyle={presetStyle}
                        />
                    </Col>
                </Row>
            </ProForm>
        </>
    );
}
