import React from 'react';
import {Input, Divider} from 'antd';
import {ProForm, ProFormRadio, ProFormSwitch} from '@ant-design/pro-form';
import {LabelField, type AxisDirectionType} from '@yookue/ant-buddy-pro';
import {type LabelPresetStyle} from '@yookue/ant-buddy-pro/field/LabelField';


export default () => {
    const [layout, setLayout] = React.useState<AxisDirectionType>('horizontal');
    const [required, setRequired] = React.useState<boolean>(false);
    const [presetStyle, setPresetStyle] = React.useState<LabelPresetStyle | false>('field-prior');

    return (
        <>
            <ProForm
                name='LabelField_demo.en-US'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormRadio.Group
                    label='Layout'
                    radioType='button'
                    fieldProps={{
                        value: layout,
                        buttonStyle: 'solid',
                        onChange: (event) => {
                            setLayout(event.target?.value);
                            if (event.target?.value === 'vertical') {
                                setPresetStyle(false);
                            }
                        }
                    }}
                    options={[
                        {label: 'Horizontal', value: 'horizontal'},
                        {label: 'Vertical', value: 'vertical'},
                    ]}
                />
                <ProFormSwitch
                    label='Required'
                    checkedChildren='True'
                    unCheckedChildren='False'
                    fieldProps={{
                        checked: required,
                        onChange: setRequired,
                    }}
                />
                <ProFormRadio.Group
                    label='Preset Style'
                    radioType='button'
                    fieldProps={{
                        value: presetStyle,
                        buttonStyle: 'solid',
                        disabled: layout !== 'horizontal',
                        onChange: (event) => {
                            setPresetStyle(event.target?.value);
                        }
                    }}
                    options={[
                        {label: 'Label-Prior', value: 'label-prior'},
                        {label: 'Field-Prior', value: 'field-prior'},
                        {label: 'False', value: false},
                    ]}
                />
            </ProForm>
            <Divider/>
            <LabelField
                label='Username'
                layout={layout}
                required={required}
                presetStyle={presetStyle}
            >
                <Input placeholder='Username'/>
            </LabelField>
        </>
    );
}
