import React from 'react';
import {Divider} from 'antd';
import {LockOutlined} from '@ant-design/icons';
import {ProForm, ProFormText, ProFormRadio, ProFormSwitch} from '@ant-design/pro-form';
import {CipherStrength, type BeforeAfterType} from '@yookue/ant-buddy-pro';


export default () => {
    const [widthBlock, setWidthBlock] = React.useState<boolean>(false);
    const [captionPos, setCaptionPos] = React.useState<BeforeAfterType>('after');

    return (
        <>
            <ProForm
                name='CipherStrength_demo.en-US'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormSwitch
                    label='Width Block'
                    checkedChildren='True'
                    unCheckedChildren='False'
                    fieldProps={{
                        checked: widthBlock,
                        onChange: setWidthBlock,
                    }}
                />
                <ProFormRadio.Group
                    label='Caption Position'
                    radioType='button'
                    fieldProps={{
                        value: captionPos,
                        buttonStyle: 'solid',
                        onChange: (event) => {
                            setCaptionPos(event.target?.value);
                        }
                    }}
                    options={[
                        {label: 'Before', value: 'before'},
                        {label: 'After', value: 'after'},
                        {label: 'False', value: false},
                    ]}
                />
                <Divider/>
                <ProFormText.Password
                    name='password'
                    label='Password'
                    placeholder='Password'
                    fieldProps={{
                        allowClear: true,
                        autoComplete: 'new-password',
                        prefix: <LockOutlined/>
                    }}
                />
                <CipherStrength
                    watchField='password'
                    widthBlock={widthBlock}
                    captionPos={captionPos}
                    locale='en_US'
                />
            </ProForm>
        </>
    );
}
